const state = { index: null, classData: new Map(), activeClass: null, activeSubject: null, activeCategory: null, query: '', visibleLimit: 36, view: 'home', studySpace: null, studyMode: false };
const ACCENTS = ['#c8ff3d', '#6fe7ff', '#ff9a76', '#b998ff', '#ffd166', '#c8ff3d'];
const $ = (selector, parent = document) => parent.querySelector(selector);
const $$ = (selector, parent = document) => [...parent.querySelectorAll(selector)];
function escapeHtml(value = '') { return String(value).replace(/[&<>'"]/g, (char) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[char])); }
function formatCount(value) { return new Intl.NumberFormat('en-US').format(value || 0); }
function classSummary(key) { return state.index?.classes.find((item) => item.class === key); }
function scrollToId(id) { document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
function updateUrl() { const url = new URL(window.location.href); state.view === 'home' ? url.searchParams.delete('class') : state.activeClass ? url.searchParams.set('class', state.activeClass) : url.searchParams.delete('class'); if (state.activeSubject) url.searchParams.set('subject', state.activeSubject); else url.searchParams.delete('subject'); if (state.activeCategory) url.searchParams.set('category', state.activeCategory); else url.searchParams.delete('category'); history.replaceState({}, '', `${url.pathname.split('/').pop() || 'index.html'}${url.search}${url.hash}`); }
function setActiveNav(name) { $$('.nav-link').forEach((button) => button.classList.toggle('is-active', button.dataset.action === name)); }
function showView(name) { ['home-view', 'class-view', 'about-view'].forEach((id) => document.getElementById(id).classList.toggle('is-hidden', id !== `${name}-view`)); setActiveNav(name === 'about' ? 'about' : 'home'); state.view = name; window.scrollTo({ top: 0, behavior: 'smooth' }); }
function setStats() { $('[data-stat="resources"]').textContent = formatCount(state.index.totalResources); $('[data-stat="classes"]').textContent = String(state.index.classes.length).padStart(2, '0'); }

function loadStudySpace() { try { const saved = JSON.parse(localStorage.getItem('bck-study-space') || 'null'); return saved && saved.class && Array.isArray(saved.subjects) ? saved : null; } catch { return null; } }
function saveStudySpaceToDevice(value) { state.studySpace = value; localStorage.setItem('bck-study-space', JSON.stringify(value)); refreshStudyHeader(); }
function refreshStudyHeader() { const button = $('.study-nav'); if (!button) return; button.classList.toggle('has-space', !!state.studySpace); button.title = state.studySpace ? `${state.studySpace.class} Study Space · ${state.studySpace.subjects.length} subjects` : 'Create a Study Space'; }
function subjectsForClass(key) { const data = fetchClassData(key); return [...new Set(data.categories.flatMap((category) => category.items.map((item) => item.subject)))].sort((a,b) => a.localeCompare(b)); }
function renderStudySubjects(key, selected = []) { const available = subjectsForClass(key); const chosen = new Set(selected); $('#study-subjects').innerHTML = available.map((subject, index) => `<label class="study-subject"><input type="checkbox" value="${escapeHtml(subject)}" ${chosen.has(subject) ? 'checked' : ''}><span>${escapeHtml(subject)}</span><b>${String(subject).slice(0,1).toUpperCase()}</b></label>`).join(''); $('#study-subject-count').textContent = `${selected.length} selected`; }
function openStudyModal() { const select = $('#study-class'); const currentClass = state.studySpace?.class || state.activeClass || 'S1'; select.innerHTML = state.index.classes.map((item) => `<option value="${item.class}" ${item.class === currentClass ? 'selected' : ''}>${item.class} · ${escapeHtml(item.label)}</option>`).join(''); renderStudySubjects(currentClass, state.studySpace?.subjects || []); $('#study-modal').classList.add('is-open'); $('#study-modal').setAttribute('aria-hidden','false'); document.body.classList.add('modal-open'); }
function closeStudyModal() { $('#study-modal').classList.remove('is-open'); $('#study-modal').setAttribute('aria-hidden','true'); document.body.classList.remove('modal-open'); }
function saveStudySpace() { const key = $('#study-class').value; const subjects = $$('input[type="checkbox"]:checked', $('#study-subjects')).map((input) => input.value); if (!subjects.length) { showToast('Choose at least one subject first.'); return; } saveStudySpaceToDevice({ class: key, subjects }); state.studyMode = true; closeStudyModal(); state.activeClass = key; state.activeSubject = null; state.query = ''; renderClassView(fetchClassData(key)); showToast(`Study Space saved · ${subjects.length} subjects`); }
function resetStudySpace() { localStorage.removeItem('bck-study-space'); state.studySpace = null; state.studyMode = false; refreshStudyHeader(); closeStudyModal(); goHome(); showToast('Study Space cleared.'); }
function activateStudySpace() { if (!state.studySpace) return openStudyModal(); state.studyMode = true; state.activeClass = state.studySpace.class; state.activeSubject = null; state.query = ''; updateUrl(); renderClassView(fetchClassData(state.activeClass)); }
function showToast(message) { const toast = $('#toast'); if (!toast) return; toast.textContent = message; toast.classList.add('is-visible'); clearTimeout(window.__toastTimer); window.__toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 2800); }
function renderGlobalSearch(query) { const panel = $('#search-results'); const term = query.trim().toLowerCase(); if (!term) { panel.hidden = true; panel.innerHTML = ''; return; } const results = []; for (const key of Object.keys(EMBEDDED_CATALOG.classes)) { const data = EMBEDDED_CATALOG.classes[key]; for (const category of data.categories) for (const item of category.items) { if (`${item.title} ${item.subject} ${data.class}`.toLowerCase().includes(term)) results.push({ ...item, class: key, category: category.key }); if (results.length >= 8) break; } if (results.length >= 8) break; } panel.innerHTML = results.length ? results.map((item) => `<button class="search-result" data-search-class="${item.class}" data-search-subject="${escapeHtml(item.subject)}" data-search-category="${item.category}"><span class="search-result-code">${item.class}</span><span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.subject)} · ${escapeHtml(item.fileName)}</small></span><b>↗</b></button>`).join('') : '<div class="search-empty">No resources found. Try another phrase.</div>'; panel.hidden = false; }
function studyFilteredSubjects(subjects) { return state.studyMode && state.studySpace ? subjects.filter((subject) => state.studySpace.subjects.includes(subject)) : subjects; }

function renderClassCards() { const classes = state.studyMode && state.studySpace ? state.index.classes.filter((item) => item.class === state.studySpace.class) : state.index.classes; $('#class-grid').innerHTML = classes.map((item, index) => `<button class="class-card" data-class="${item.class}" style="--accent:${ACCENTS[index]}"><span class="class-card-index">0${index + 1}</span><span class="class-card-code">${item.class}</span><span class="class-card-label">${escapeHtml(item.label)}</span><span class="class-card-tagline">${escapeHtml(item.tagline)}</span><span class="class-card-count">${formatCount(item.totalResources)} resources <b>↗</b></span><i aria-hidden="true"></i></button>`).join(''); }
function fetchClassData(key) { if (state.classData.has(key)) return state.classData.get(key); const data = EMBEDDED_CATALOG.classes[key]; if (!data) throw new Error(`Could not load ${key}`); state.classData.set(key, data); return data; }
function renderClassView(data) { const summary = classSummary(data.class); const subjects = studyFilteredSubjects([...new Set(data.categories.flatMap((category) => category.items.map((item) => item.subject)))].sort((a,b) => a.localeCompare(b))); const subjectCounts = subjects.map((subject) => ({ subject, count: data.categories.flatMap((category) => category.items).filter((item) => item.subject === subject).length })); $('#class-view').innerHTML = `<div class="breadcrumb"><button data-action="home">Home</button><span>/</span><strong>${data.class}</strong></div><div class="inner-hero"><div><p class="kicker"><span></span> 02 / choose a subject</p>${state.studyMode && state.studySpace ? `<span class="study-filter-badge">Study Space · ${state.studySpace.subjects.length} subjects</span>` : ``}<h1 id="class-title">${escapeHtml(data.label)}<br><em>subject map.</em></h1></div><div class="inner-hero-side"><p>${escapeHtml(summary?.tagline || data.tagline)}. Choose one subject to open its notes, papers and study resources.</p><strong>${formatCount(data.totalResources)} <small>resources across ${subjects.length} subjects</small></strong></div></div><div class="subject-toolbar"><label class="search-field"><span>⌕</span><input id="subject-search" type="search" placeholder="Find a subject…" autocomplete="off"></label><span class="toolbar-hint">Select a subject to continue <b>→</b></span></div><div id="subject-grid" class="subject-grid">${subjectCounts.map((item, index) => `<button class="subject-card" data-subject="${escapeHtml(item.subject)}" style="--accent:${ACCENTS[index % ACCENTS.length]}"><span class="subject-icon">${String(item.subject).slice(0,1).toUpperCase()}</span><span class="subject-name">${escapeHtml(item.subject)}</span><span class="subject-count">${formatCount(item.count)} resources</span><b>Open subject ↗</b></button>`).join('')}</div>`; showView('class'); }
function activeItems(data) { const category = state.activeCategory ? data.categories.find((entry) => entry.key === state.activeCategory) : null; const all = (category ? category.items : data.categories.flatMap((entry) => entry.items)); const q = state.query.trim().toLowerCase(); return all.filter((item) => { const haystack = `${item.title} ${item.subject} ${item.description}`.toLowerCase(); return item.subject === state.activeSubject && (!q || haystack.includes(q)); }); }
function renderResourceCard(item, index) { return `<article class="resource-card" style="--accent:${ACCENTS[index % ACCENTS.length]}"><div class="resource-top"><span>${escapeHtml(item.subject)}</span><b>PDF</b></div><h3 title="${escapeHtml(item.title)}">${escapeHtml(item.title)}</h3><p>${escapeHtml(item.description)} · ${escapeHtml(item.fileName)}</p><div class="resource-actions"><button data-resource-id="${escapeHtml(item.id)}">Preview <span>↗</span></button><a href="${escapeHtml(item.url)}" target="_blank" rel="noopener" download aria-label="Open ${escapeHtml(item.title)}">↓</a></div></article>`; }
function renderCategoryView(data) { const categories = data.categories.map((category) => ({ ...category, subjectItems: category.items.filter((item) => item.subject === state.activeSubject) })).filter((category) => category.subjectItems.length); $('#class-view').innerHTML = `<div class="breadcrumb"><button data-action="home">Home</button><span>/</span><button data-action="back-class">${data.class}</button><span>/</span><strong>${escapeHtml(state.activeSubject)}</strong></div><div class="inner-hero"><div><p class="kicker"><span></span> 03 / choose your resource type</p><h1 id="class-title">${escapeHtml(state.activeSubject)}<br><em>resource shelf.</em></h1></div><div class="inner-hero-side"><p>Choose what you need next: exam practice, lesson notes, holiday work or another approved collection.</p><strong>${formatCount(categories.reduce((sum, category) => sum + category.subjectItems.length, 0))} <small>resources in this subject</small></strong></div></div><div class="category-choice-grid">${categories.map((category, index) => `<button class="category-choice" data-category="${category.key}" style="--accent:${ACCENTS[index % ACCENTS.length]}"><span class="category-choice-icon">${escapeHtml(category.icon || '✦')}</span><strong>${escapeHtml(category.label)}</strong><small>${escapeHtml(category.description)}</small><b>${formatCount(category.subjectItems.length)} resources <span>↗</span></b></button>`).join('')}</div>`; showView('class'); }
function renderResourcesView(data) { const items = activeItems(data); const visible = items.slice(0, state.visibleLimit); const subject = state.activeSubject || 'All subjects'; const category = data.categories.find((entry) => entry.key === state.activeCategory); const categoryLabel = category?.label || 'Resources'; $('#class-view').innerHTML = `<div class="breadcrumb"><button data-action="home">Home</button><span>/</span><button data-action="back-class">${data.class}</button><span>/</span><button data-action="back-subject">${escapeHtml(subject)}</button><span>/</span><strong>${escapeHtml(categoryLabel)}</strong></div><div class="resource-heading"><div><p class="kicker"><span></span> 04 / your resource shelf</p><h1>${escapeHtml(categoryLabel)}<br><em>for ${escapeHtml(subject)}.</em></h1></div><div class="resource-heading-side"><p>${escapeHtml(category?.description || 'Approved study material')} for ${data.class}.</p><strong>${formatCount(items.length)} <small>matching resources</small></strong></div></div><div class="resource-toolbar"><button class="back-button" data-action="back-subject">← Change resource type</button><label class="search-field"><span>⌕</span><input id="resource-search" type="search" placeholder="Search this shelf…" value="${escapeHtml(state.query)}" autocomplete="off"></label></div><div class="resource-grid">${visible.length ? visible.map(renderResourceCard).join('') : `<div class="empty-state"><strong>No matching resources.</strong><p>Try another search term or return to the resource types.</p></div>`}</div>${items.length > visible.length ? `<div class="load-more"><button class="outline-button" data-action="load-more">Load 36 more <span>↓</span></button></div>` : ''}<p class="results-note">Source catalogue · links open the original file location</p>`; showView('class'); }
function openClass(key) { try { state.activeClass = key; state.activeSubject = null; state.activeCategory = null; state.query = ''; state.visibleLimit = 36; updateUrl(); renderClassView(fetchClassData(key)); } catch (error) { renderError(error.message); } }
function openSubject(subject) { state.activeSubject = subject; state.activeCategory = null; state.query = ''; state.visibleLimit = 36; updateUrl(); renderCategoryView(fetchClassData(state.activeClass)); }
function openCategory(category) { state.activeCategory = category; state.query = ''; state.visibleLimit = 36; updateUrl(); renderResourcesView(fetchClassData(state.activeClass)); }
function goHome() { state.activeClass = null; state.activeSubject = null; state.activeCategory = null; state.query = ''; renderClassCards(); updateUrl(); showView('home'); }
function renderAbout() { $('#about-view').innerHTML = `<div class="breadcrumb"><button data-action="home">Home</button><span>/</span><strong>About</strong></div><div class="about-hero"><div class="about-badge"><img src="school-badge.png" alt="BCK school badge"></div><div><p class="kicker"><span></span> About BCK Digital Library</p><h1 id="about-title">A better place<br><em>to study.</em></h1><p>The BCK Digital Library is a student-led learning access project for Bishop Cipriano Kihangire Senior Secondary School Day Section. It brings approved study resources into one focused, searchable space so learners can revise with less friction and make more purposeful use of their gadgets.</p></div></div><div class="about-grid"><article><span>01</span><h3>Find the right shelf</h3><p>Start with S1–S6, choose your subject, then select the resource type you need — past papers, notes, holiday packages and other approved collections.</p></article><article><span>02</span><h3>Build your Study Space</h3><p>Choose a class and the subjects you are currently working on. Your browser remembers the setup and keeps the library focused around your priorities.</p></article><article><span>03</span><h3>Learn responsibly</h3><p>Resources should be used for educational and productive purposes and shared only when the school or copyright owner has granted the necessary permission.</p></article></div><div class="about-details"><div><p class="kicker"><span></span> How it works</p><h2>From a class<br>to a clear next step.</h2></div><ol><li><b>01</b><span><strong>Choose a class</strong>Select the level that matches your current year.</span></li><li><b>02</b><span><strong>Choose a subject</strong>Open the subject map and focus on one area at a time.</span></li><li><b>03</b><span><strong>Choose a resource type</strong>Move between past papers, notes and other collections.</span></li><li><b>04</b><span><strong>Open or download</strong>Preview a file in the library or open its original link.</span></li></ol></div><div class="team-panel"><div><p class="kicker"><span></span> Development team</p><h2>Built by<br>students.</h2><p class="about-muted">The library is maintained as a practical digital learning initiative for the BCK community.</p></div><div class="people"><div class="person"><b>AE</b><div><small>CHIEF DEVELOPER</small><strong>Ainembabazi Edward Francis</strong><span>Product direction · catalogue experience · development</span></div></div><div class="person"><b>MV</b><div><small>ASSISTANT CHIEF DEVELOPER</small><strong>Mataa Victor</strong><span>Development support · improvements · testing</span></div></div></div></div><div class="contact-panel"><div><p class="kicker">Contact the Chief Developer</p><h2>Have a suggestion<br>or resource?</h2><p>For feedback about the website, approved learning materials or technical issues, contact Ainembabazi Edward Francis.</p><p><strong>Ainembabazi Edward Francis</strong> · Chief Developer</p><p>+256 741 219 802 · edwardfrancis007242002@gmail.com</p></div><div class="contact-actions"><a href="https://wa.me/256741219802" target="_blank" rel="noopener">WhatsApp ↗</a><a href="mailto:edwardfrancis007242002@gmail.com">Email ↗</a></div></div>`; showView('about'); }
function renderError(message) { $('#class-view').innerHTML = `<div class="empty-state"><strong>Library unavailable.</strong><p>${escapeHtml(message)}</p><button class="primary-button" data-action="home">Back home <span>↖</span></button></div>`; showView('class'); }
function showReader(resource) { $('#reader-title').textContent = resource.title; $('#reader-meta').textContent = `${resource.subject} · ${resource.fileName}`; $('#reader-download').href = resource.url; $('#reader-frame').src = resource.url; $('#reader-modal').classList.add('is-open'); $('#reader-modal').setAttribute('aria-hidden','false'); document.body.classList.add('modal-open'); }
function closeReader() { $('#reader-modal').classList.remove('is-open'); $('#reader-modal').setAttribute('aria-hidden','true'); document.body.classList.remove('modal-open'); $('#reader-frame').src = 'about:blank'; }
function currentResource(id) { return fetchClassData(state.activeClass).categories.flatMap((category) => category.items).find((item) => item.id === id); }
function bindEvents() { document.addEventListener('click', (event) => { const searchResult = event.target.closest('[data-search-class]'); if (searchResult) { $('#global-search').value = ''; renderGlobalSearch(''); state.studyMode = false; state.activeClass = searchResult.dataset.searchClass; state.activeSubject = searchResult.dataset.searchSubject; state.activeCategory = searchResult.dataset.searchCategory || null; state.query = ''; renderResourcesView(fetchClassData(state.activeClass)); return; } const classButton = event.target.closest('[data-class]'); if (classButton) return openClass(classButton.dataset.class); const categoryButton = event.target.closest('[data-category]'); if (categoryButton) return openCategory(categoryButton.dataset.category); const subjectButton = event.target.closest('[data-subject]'); if (subjectButton) return openSubject(subjectButton.dataset.subject); const resourceButton = event.target.closest('[data-resource-id]'); if (resourceButton) { const item = currentResource(resourceButton.dataset.resourceId); if (item) showReader(item); return; } const action = event.target.closest('[data-action]')?.dataset.action; if (action === 'home') return goHome(); if (action === 'about') return renderAbout(); if (action === 'study-space') return activateStudySpace(); if (action === 'close-study') return closeStudyModal(); if (action === 'save-study') return saveStudySpace(); if (action === 'reset-study') return resetStudySpace(); if (action === 'back-class') { state.activeSubject = null; state.activeCategory = null; return renderClassView(fetchClassData(state.activeClass)); } if (action === 'back-subject') { return renderCategoryView(fetchClassData(state.activeClass)); } if (action === 'close-reader') return closeReader(); if (action === 'load-more') { state.visibleLimit += 36; return renderResourcesView(fetchClassData(state.activeClass)); } const scroll = event.target.closest('[data-scroll]')?.dataset.scroll; if (scroll) scrollToId(scroll); }); document.addEventListener('input', (event) => { if (event.target.id === 'global-search') { renderGlobalSearch(event.target.value); } if (event.target.id === 'subject-search') { const query = event.target.value.toLowerCase(); $$('.subject-card').forEach((card) => card.hidden = !card.dataset.subject.toLowerCase().includes(query)); } if (event.target.id === 'study-class') { renderStudySubjects(event.target.value, []); } if (event.target.id === 'resource-search') { state.query = event.target.value; state.visibleLimit = 36; renderResourcesView(fetchClassData(state.activeClass)); const input = $('#resource-search'); input?.focus(); input?.setSelectionRange(input.value.length, input.value.length); } }); document.addEventListener('change', (event) => { if (event.target.id === 'study-class') renderStudySubjects(event.target.value, []); if (event.target.closest('#study-subjects')) $('#study-subject-count').textContent = `${$$('input[type="checkbox"]:checked', $('#study-subjects')).length} selected`; }); document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeReader(); }); window.addEventListener('popstate', () => { const params = new URLSearchParams(window.location.search); if (params.get('class') && params.get('subject')) { state.activeClass = params.get('class'); state.activeSubject = params.get('subject'); renderResourcesView(fetchClassData(state.activeClass)); } else if (params.get('class')) openClass(params.get('class')); else goHome(); }); }
function init() { bindEvents(); try { const params = new URLSearchParams(window.location.search); const initialClass = params.get('class'); const initialSubject = params.get('subject'); const initialCategory = params.get('category'); state.studySpace = loadStudySpace(); refreshStudyHeader(); state.index = EMBEDDED_CATALOG.index; setStats(); renderClassCards(); renderAbout(); goHome(); if (initialClass && initialSubject) { state.activeClass = initialClass; state.activeSubject = initialSubject; state.activeCategory = initialCategory || null; if (state.activeCategory) renderResourcesView(fetchClassData(state.activeClass)); else renderCategoryView(fetchClassData(state.activeClass)); } else if (initialClass) openClass(initialClass); } catch (error) { $('#class-grid').innerHTML = `<div class="empty-state"><strong>Library unavailable.</strong><p>${escapeHtml(error.message)}</p></div>`; } }
init();
